  layAreaStart_event: ["Central event space", "중앙 행사 공간", "中央活动空间", "中央のイベントスペース", "Espacio central para eventos", "Espace central d’événements"],
  layAreaName_custom: ["Reserved area", "예약 공간", "预留区域", "予約エリア", "Zona reservada", "Zone réservée"],
