  layMoveAreaTo: ["Move area to", "공간 이동", "移动区域到", "エリアの移動先", "Mover la zona a", "Déplacer la zone vers"],
  layAreaPos_back_left: ["Back left", "뒤 왼쪽", "后左", "奥の左", "Fondo izquierda", "Fond gauche"],
  layAreaPos_back_right: ["Back right", "뒤 오른쪽", "后右", "奥の右", "Fondo derecha", "Fond droit"],
